mapper.select:
SELECT id, event_id, event_type, aggregate_type, aggregate_key, payload, status, occurred_at, next_retry_time, retry_count, tenant_id, creator, create_time, updater, update_time FROM plt_outbox_event WHERE tenant_id = #{query.tenantId} AND event_type IN
#{eventType}
AND status = 'PENDING' AND (next_retry_time IS NULL OR next_retry_time <= #{query.dueAt}) ORDER BY COALESCE(next_retry_time, occurred_at), id LIMIT #{query.limit} FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE plt_outbox_event
SET status = 'DELIVERED', next_retry_time = NULL, update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{query.tenantId}
  AND event_id = #{query.eventId}
  AND status = 'PENDING'
  AND retry_count = #{query.expectedRetryCount}

UPDATE plt_outbox_event
SET retry_count = retry_count + 1,
    next_retry_time = #{query.nextRetryTime},
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{query.tenantId}
  AND event_id = #{query.eventId}
  AND status = 'PENDING'
  AND retry_count = #{query.expectedRetryCount}
